// Classic Blink — the Hello World of embedded systems
// Works on Arduino Uno, Nano, Mega, ESP32, and most others

const int LED = 13;  // built-in LED on most Arduino boards

void setup() {
  // Called ONCE at power-on or after reset
  pinMode(LED, OUTPUT);
  Serial.begin(115200);  // open serial port at 115200 baud
  Serial.println(F("Blink sketch started!"));
  // F() stores the string in flash instead of SRAM
}

void loop() {
  // Called CONTINUOUSLY, forever
  digitalWrite(LED, HIGH);         // 5V on pin
  Serial.println(F("LED ON"));
  delay(1000);                     // pause 1000 ms

  digitalWrite(LED, LOW);          // 0V on pin
  Serial.println(F("LED OFF"));
  delay(1000);
}

// Example: using the DHT sensor library
// 1. Install: Tools → Library Manager → search "DHT sensor library" by Adafruit
#include <DHT.h>

#define DHT_PIN  4
#define DHT_TYPE DHT22
DHT dht(DHT_PIN, DHT_TYPE);

void setup() {
  Serial.begin(115200);
  dht.begin();
  Serial.println(F("DHT22 sensor initialised"));
}

void loop() {
  float humidity    = dht.readHumidity();
  float temperature = dht.readTemperature();

  if (isnan(humidity) || isnan(temperature)) {
    Serial.println(F("Failed to read from DHT sensor!"));
    return;
  }

  Serial.print(F("Temp: "));
  Serial.print(temperature);
  Serial.print(F("°C  Humidity: "));
  Serial.print(humidity);
  Serial.println(F("%"));
  delay(2000);
}

const int LED_PIN = 13;
const long INTERVAL = 1000;  // ms between toggles

unsigned long lastToggle = 0;
bool ledState = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  unsigned long now = millis();

  // Check if 1000ms has passed since last toggle
  if (now - lastToggle >= INTERVAL) {
    lastToggle = now;
    ledState = !ledState;
    digitalWrite(LED_PIN, ledState);
    Serial.print(F("LED: ")); Serial.println(ledState ? F("ON") : F("OFF"));
  }

  // Other code here runs EVERY loop iteration
  // — no blocking!
}

void setup() {
  Serial.begin(115200);           // set baud rate
  while (!Serial) delay(10);     // wait for USB serial on Leonardo/Micro
  Serial.println(F("=== Debug mode ==="));
}

void loop() {
  // Print multiple values on one line
  Serial.print(F("A0=")); Serial.print(analogRead(A0));
  Serial.print(F(" A1=")); Serial.print(analogRead(A1));
  Serial.print(F(" uptime=")); Serial.print(millis() / 1000);
  Serial.println(F("s"));

  // Read command from Serial Monitor
  if (Serial.available()) {
    char c = Serial.read();
    if (c == 'r') {               // type 'r' to reset
      Serial.println(F("Resetting..."));
      asm volatile ("jmp 0");    // soft reset AVR
    }
  }
  delay(500);
}
